function mt2009_arezzo_closed($sqlServ) {
	static $closed = null;
	if ($closed === null) {
		$row = null;
		try {   // PHP 8.1+ throws on a failed query; a flag nobody can read keeps the sets hidden
			$r = mysqli_query($sqlServ, "SELECT lValue FROM player.quest WHERE dwPID = 0 AND szName = 'mt2009_arezzo_closed' LIMIT 1");
			$row = $r ? mysqli_fetch_row($r) : null;
		} catch (Throwable $e) {
			$row = null;
		}
		$closed = !$row || (int)$row[0] > 0;
	}
	return $closed;
}

// " AND <col> NOT IN (...)" while the module is off, "" while it is on.
function mt2009_arezzo_costume_sql($sqlServ, $col = 'vnum') {
