}

function mt2009_arezzo_costume_locked($sqlServ, $vnum) {
	return in_array((string)(int)$vnum, explode(',', MT2009_AREZZO_COSTUME_VNUMS), true) && mt2009_arezzo_closed($sqlServ);
}
